Definition mid (fxi : FPState) (Ri : bvmap 5 word) (Mi : word -> option byte) (mdi : Model) (cri : credit)
           (si : PM.pst) (smi : PM.strm) (eni : PEC.enc) (ki : PESK.sink) (ei : bool) (Xi : st) : Prop :=
  getr Ri (PMK.reg 2) = Z_to_bv 64 (sp - 112) /\ getr Ri (PMK.reg 8) = Z_to_bv 64 (fb + 48) /\ getr Ri (PMK.reg 9) = Z_to_bv 64 (fb + 16)
  /\ getr Ri (PMK.reg 18) = Z_to_bv 64 (fb + 440) /\ csk Ri
  /\ saved Mi
  /\ L5C.stk (hl_sptop L) Mi sp 26624 /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (PEC.owned si eni ki ++ LBX) cri Mi (m_vmmaps mdi)
  /\ PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P Mi fb p Xi si str smi eni ki ei cat
  /\ PMSP.src_step (PM.p_src s) (PM.p_src si) sm smi /\ (e = true -> ei = true)
  /\ PMK.ek L LBX sp 26624 (PEC.W_crun CAD EE fb) M Mi /\ PMK.dk L LBX sp 26624 M Mi
  /\ PMSP.credit_keep cr cri (PEC.pot_all L P s en k) (PEC.pot_all L P si eni ki).

