(* [comment removed for export] *)
Lemma call_ignore (q : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_more Y = true -> s_done Y = false -> s_pos Y < blen p ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q -> getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 48 + 24) -> getr Ri (PMK.reg 11) = Z_to_bv 64 1 ->
  (forall fx2 R2 M2 si2 sm2, regs_preserved Ri R2 ->
      mid fx2 R2 M2 mdi cri si2 sm2 eni ki ei (w_pos (s_pos Y + 1) Y) ->
      L5C.agree_on Mi M2 (sp - 112) 48 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 mdi) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri 0x38f24 Mi mdi) K.
Proof.
