(* [comment removed for export] *)
Lemma push_mid (t : UbjRef.pstate) fxi Ri Mi mdi cri si smi eni ki ei Y fx2 R2 M2 :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  Z.of_nat (length (PM.p_stk si)) < 2 ^ (PM.p_k si) ->
  mem_grows Mi M2 ->
  (forall i, 0 <= i < 2 ^ 64 ->
     ~ (PM.p_b si + 32 * Z.of_nat (length (PM.p_stk si)) <= i < PM.p_b si + 32 * Z.of_nat (length (PM.p_stk si)) + 32) ->
     ~ (fb + 48 + 368 <= i < fb + 48 + 376) -> ~ (sp - 128 <= i < sp - 64) -> M2 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  PM.pstate_at RSEGS M2 (PM.p_b si + 32 * Z.of_nat (length (PM.p_stk si))) (PEC.ps_conv t) ->
  L5.u64_at RSEGS M2 (fb + 48 + 368) (PM.p_b si + 32 * Z.of_nat (length (PM.p_stk si)) + 32) ->
  getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R2 (PMK.reg 8) = Z_to_bv 64 (fb + 48) -> getr R2 (PMK.reg 9) = Z_to_bv 64 (fb + 16) ->
  getr R2 (PMK.reg 18) = Z_to_bv 64 (fb + 440) -> csk R2 ->
