Lemma grow_rest_C (n : Z) fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y fx1 R1 M1 :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y -> s_ec Y = false ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 -> 0 <= n <= 16777216 ->
  mem_grows Mi M1 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 128 <= i < sp - 112) -> ~ (sp - 72 <= i < sp - 64) -> M1 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  (forall j, In j CSK -> getr R1 (PMK.reg j) = getr Ri (PMK.reg j)) ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 0x38400 -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 128) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (2 ^ (vki + 1)) ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 (fb + 16) -> getr R1 (PMK.reg 10) = Z_to_bv 64 (32 * 2 ^ (vki + 1)) -> getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 440) ->
  getr R1 (PMK.reg 19) = Z_to_bv 64 n -> getr R1 (PMK.reg 20) = Z_to_bv 64 (32 * 2 ^ vki) ->
  L5.u64_at RSEGS M1 (sp - 128) (fb + 48) -> L5.u64_at RSEGS M1 (sp - 120) 0x39c54 -> L5.u64_at RSEGS M1 (sp - 72) (fb + 48 + 360) ->
  hi_heap HI (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX) cri M1 (m_vmmaps mdi) ->
  (forall fx2 R2 M2 md2 B,
      mid fx2 R2 M2 md2 (debit L cri (32 * 2 ^ (vki + 1))) (PM.PST moi dni dpi srci tbi tgi B (vki + 1) (stki ++ [PEC.ps_conv (PS Marray n 0 0)])) smi eni ki ei
          (w_stk (PS Marray n 0 0 :: s_stk Y) Y) ->
      getr R2 (PMK.reg 1) = Z_to_bv 64 0x39d60 -> getr R2 (PMK.reg 10) = Z_to_bv 64 (fb + 440) -> getr R2 (PMK.reg 11) = Z_to_bv 64 n ->
