(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma grow_alloc_T (n : Z) fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y -> s_ec Y = false ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 ->
  getr Ri (PMK.reg 10) = Z_to_bv 64 n -> getr Ri (PMK.reg 19) = Z_to_bv 64 (fb + 48 + 24) -> 0 <= n <= 16777216 -> getr Ri (PMK.reg 20) = Z_to_bv 64 1 ->
  (forall fx1 R1 M1, mem_grows Mi M1 ->
      (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 128 <= i < sp - 112) -> ~ (sp - 72 <= i < sp - 64) -> M1 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
      (forall j, In j CSK -> getr R1 (PMK.reg j) = getr Ri (PMK.reg j)) ->
      getr R1 (PMK.reg 1) = Z_to_bv 64 0x38400 -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 128) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (2 ^ (vki + 1)) ->
      getr R1 (PMK.reg 9) = Z_to_bv 64 (fb + 16) -> getr R1 (PMK.reg 10) = Z_to_bv 64 (32 * 2 ^ (vki + 1)) -> getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 440) ->
      getr R1 (PMK.reg 19) = Z_to_bv 64 n -> getr R1 (PMK.reg 20) = Z_to_bv 64 (32 * 2 ^ vki) ->
      L5.u64_at RSEGS M1 (sp - 128) (fb + 48) -> L5.u64_at RSEGS M1 (sp - 120) 0x39ccc -> L5.u64_at RSEGS M1 (sp - 72) (fb + 48 + 360) ->
      hi_heap HI (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX) cri M1 (m_vmmaps mdi) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xb13c4 M1 mdi) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fxi Ri 0x39a5c Mi mdi) K.
Proof.
Local Ltac galloct PC fxi Ri Mi mdi cri K sp fb vbi n STK HHi Mh Ml KX X9 X18 :=
    pose proof (PC fxi Ri Mi (fun j => match j with 2%nat => sp | 34%nat => vbi | 36%nat => fb + 48 | 37%nat => fb + 440 | 38%nat => fb + 16 | 48%nat => n | _ => 0 end)) as PA1;
    cbn beta iota in PA1;
    PMK.feed PA1 ltac:(first [PMK.sc | progress (unfold PESBGP2.aligned); first [assumption | (clear; lia)] | lia ]);
    destruct PA1 as (fx1 & R1 & M1 & MG1 & _ & FRZ1 & MS1 & KS1 & Y1 & Y2 & Y8 & Y10 & Y11 & Y12 & Y13 & Y14 & Y19 & Y20 & C128 & C120 & C72);
    apply (PMK.spiece RSEGS L HI KL HIok _ cri Mi mdi fxi fx1 Ri 0x39a04 R1 0xb1378 M1 (fun a => (sp - 128 <= a < sp - 128 + 16) \/ (sp - 72 <= a < sp - 72 + 8)) K HHi Mh Ml ltac:(lia) MS1 MG1);
    [ intros a Ha N; apply FRZ1; [exact Ha| intros HX; apply N; left; exact HX| intros HX; apply N; right; exact HX]
    | intros a Pa; apply (PMK.cwr_stack L _ Mi sp 26624 a STK); lia
    | intros a; apply PMK.or_dec; apply PMK.rng_dec
    | intros HH1; apply (KX fx1 R1 M1 MG1);
      [ intros i Hi N1 N2; apply FRZ1; [exact Hi| clear - N1; lia| clear - N2; lia]
      | intros j Hj; apply KS1; clear - Hj; cbn in Hj; decompose [or] Hj; subst; first [PMK.inl | contradiction]
