(* [comment removed for export] *)
Lemma entry_mid fx1 R1 M1 :
  mem_grows M M1 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 64 <= i < sp - 64 + 64) -> ~ (fb + 48 + 12 <= i < fb + 48 + 12 + 4) -> M1 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) ->
  L5.u32_at RSEGS M1 (fb + 48 + 12) (dp + 1) -> dp + 1 <= PM.MAX_DEPTH + 1 ->
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (fb + 48) -> getr R1 (PMK.reg 9) = Z_to_bv 64 (fb + 16) ->
  getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 440) -> csk R1 ->
  L5.u64_at RSEGS M1 (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) -> L5.u64_at RSEGS M1 (sp - 16) (bv_unsigned (getr R (PMK.reg 8))) ->
  L5.u64_at RSEGS M1 (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) -> L5.u64_at RSEGS M1 (sp - 32) (bv_unsigned (getr R (PMK.reg 18))) ->
  L5.u64_at RSEGS M1 (sp - 40) (bv_unsigned (getr R (PMK.reg 19))) -> L5.u64_at RSEGS M1 (sp - 48) (bv_unsigned (getr R (PMK.reg 20))) ->
  L5.u64_at RSEGS M1 (sp - 56) (bv_unsigned (getr R (PMK.reg 21))) -> L5.u64_at RSEGS M1 (sp - 64) (bv_unsigned (getr R (PMK.reg 22))) ->
  hi_heap HI (PEC.owned s en k ++ LBX) cr M1 (m_vmmaps model) ->
  mid fx1 R1 M1 model cr (PM.PST mo dn (dp + 1) (PM.SRC qc de rem) tb tg vb vk stk) sm en k e (PECBD.X1 X).
Proof.
