Lemma push_slot_C (n : Z) (Xg : st) pos1 fx4 R4 M4 md4 cr4 si4 sm4 e4 :
  mid fx4 R4 M4 md4 cr4 si4 sm4 en k e4 (w_pos pos1 Xg) -> s_ec X = false -> 0 <= n <= 16777216 ->
  getr R4 (PMK.reg 10) = Z_to_bv 64 n -> getr R4 (PMK.reg 19) = Z_to_bv 64 (fb + 48 + 24) ->
  s_more Xg = true -> s_ec Xg = s_ec X -> s_stk Xg = s_stk X -> s_estk Xg = s_estk X -> s_edepth Xg = s_edepth X -> s_lo Xg = s_lo X -> s_hi Xg = s_hi X -> s_bad Xg = s_bad X ->
